// Data-driven tests for batch89:
//   platform/product/common/productService.ts
//   amdX.ts (AMD module importer)
// Truth generated by tool/ts2dart/_batch89_truth.cjs from real TS sources.
import 'dart:convert';

import 'package:flutter_test/flutter_test.dart';
import 'package:semi_design_flutter/src/monaco/amdX.dart' as amd;
import 'package:semi_design_flutter/src/monaco/platform/product/common/productService.dart'
    as ps;

Map<String, dynamic> _truth() =>
    (jsonDecode(_truthJson) as Map).cast<String, dynamic>();

void main() {
  final t = _truth();

  group('batch89 productService.ts', () {
    test('decorator id and productSchemaId match TS truth', () {
      final e = (t['productService'] as Map).cast<String, dynamic>();
      // TS runtime exports are IProductService + productSchemaId (interface erased).
      expect(e['exports'], <dynamic>['IProductService', 'productSchemaId']);
      expect(ps.IProductService.serviceId, e['decoratorId']);
      expect(ps.IProductService.serviceId, e['serviceId']);
      expect(ps.productSchemaId, e['productSchemaId']);
      expect(ps.productSchemaId, 'vscode://schemas/vscode-product');
    });
  });

  group('batch89 amdX.ts', () {
    setUp(() {
      // Reset replaceable environment carriers between tests.
      amd.amdDefine = null;
      amd.amdProductJson = null;
      amd.amdVscodeContextProduct = null;
      amd.amdIsElectron = () => false;
      amd.amdIsWebWorker = () => false;
      amd.amdHasElectronUserAgent = () => false;
      amd.amdAsBrowserUri = (p) => 'vscode-file://vscode-app/$p';
      amd.amdLoadScript = null;
      amd.amdWarn = null;
    });

    String resolve() => amd.resolveAmdNodeModulePath('mypkg', 'release/main.js');

    test('resolveAmdNodeModulePath: built + Electron -> ASAR', () {
      amd.amdProductJson = <String, Object?>{'commit': 'abc123'};
      amd.amdIsElectron = () => true;
      expect(resolve(), t['resolveBuiltElectron']);
    });

    test('resolveAmdNodeModulePath: built + WebWorker + Electron UA -> ASAR', () {
      amd.amdProductJson = <String, Object?>{'commit': 'abc123'};
      amd.amdIsWebWorker = () => true;
      amd.amdHasElectronUserAgent = () => true;
      expect(resolve(), t['resolveBuiltWebWorkerElectronUA']);
    });

    test('resolveAmdNodeModulePath: built plain -> node_modules', () {
      amd.amdProductJson = <String, Object?>{'commit': 'abc123'};
      expect(resolve(), t['resolveBuiltPlain']);
    });

    test('resolveAmdNodeModulePath: unbuilt -> node_modules', () {
      amd.amdProductJson = <String, Object?>{};
      expect(resolve(), t['resolveUnbuilt']);
    });

    test('resolveAmdNodeModulePath: vscode context fallback -> ASAR', () {
      amd.amdVscodeContextProduct = () => <String, Object?>{'commit': 'fallback'};
      amd.amdIsElectron = () => true;
      expect(resolve(), t['resolveFallbackBuilt']);
    });

    test('importAMDNodeModule: URL pass-through + external define', () async {
      final calls = <Map<String, Object?>>[];
      amd.amdDefine = (id, deps, cb) {
        calls.add(<String, Object?>{
          'id': id,
          'deps': deps,
          'cbType': 'function',
        });
        cb(<String, Object?>{'loadedFrom': deps[0]});
      };
      final result = await amd.importAMDNodeModule<Map<String, Object?>>(
          'https://example.com/foo.js', '');
      final e = (t['importUrl'] as Map).cast<String, dynamic>();
      expect(result['loadedFrom'], e['loadedFrom']);
      expect(calls.length, (e['defineCalls'] as List).length);
      final call = (e['defineCalls'] as List).first as Map;
      expect(calls.first['deps'], call['deps']);
      expect(calls.first['cbType'], call['cbType']);
      expect(calls.first['id'], isA<String>()); // generateUuid()
    });

    test('importAMDNodeModule: node_modules path + cache identity', () async {
      final calls = <List<Object?>>[];
      amd.amdDefine = (id, deps, cb) {
        calls.add(List<Object?>.from(deps));
        cb(<String, Object?>{'loadedFrom': deps[0]});
      };
      amd.amdProductJson = <String, Object?>{};
      final result = await amd.importAMDNodeModule<Map<String, Object?>>(
          'mypkg', 'release/main.js');
      final e = (t['importNode'] as Map).cast<String, dynamic>();
      expect(result['loadedFrom'], e['loadedFrom']);
      expect(calls.length, 1);

      // Second call for same key: cache hit, same object, no new define.
      final cached = await amd.importAMDNodeModule<Map<String, Object?>>(
          'mypkg', 'release/main.js');
      final c = (t['cache'] as Map).cast<String, dynamic>();
      expect(identical(cached, result), c['sameResult']);
      expect(calls.length, c['defineCallsAfterCached']);
    });
  });
}

const String _truthJson = r'''
