    "serviceId": "productService",
    "productSchemaId": "vscode://schemas/vscode-product"
  },
  "resolveBuiltElectron": "vscode-file://vscode-app/vs/../../node_modules.asar/mypkg/release/main.js",
  "resolveBuiltWebWorkerElectronUA": "vscode-file://vscode-app/vs/../../node_modules.asar/mypkg/release/main.js",
  "resolveBuiltPlain": "vscode-file://vscode-app/vs/../../node_modules/mypkg/release/main.js",
  "resolveUnbuilt": "vscode-file://vscode-app/vs/../../node_modules/mypkg/release/main.js",
  "resolveFallbackBuilt": "vscode-file://vscode-app/vs/../../node_modules.asar/mypkg/release/main.js",
